export interface ProducerCitation { schema_version: "producer-citation@1"; citation_id: string; source_id: string; document_id: string; filename: string; media_type: "application/pdf" | "text/plain" | "text/html"; source_kind: ProducerSourceKind | "external_research"; source_label: string; source_locations: unknown[]; excerpt: string }
