export interface ProducerCanonicalItem extends ProducerStatement { value?: string | null; field?: string; amount?: string | number | null; currency?: string | null; unit?: string | null; assertions?: ProducerCanonicalItem[]; question?: string; title?: string; related_to?: string | null; element_id?: string; department?: string | null; inference_basis?: string; priority_basis?: string; limitations?: string[] }
export interface ProducerRegisterEntry { schema_version: "producer-register-entry@1"; register_id: string; type: "decision" | "question"; title: string; action: string; owner_role: string; priority: "high" | "medium" | "low"; status: "open"; claim_type: "fact" | "inference" | "unknown"; citation_ids: string[]; source_ids: string[] }
// `producer-intake-decision-packet@1` is the PRD-target strict bounded contract (one primary_screenplay,
// source/version manifest, exact facts, conflicts, evidence states, and the full provenance object)
// produced by the `/v1/producer-source-bundles` path. `producer-decision-packet@1` remains a stable,
// unrenamed compatibility alias emitted only by the older free-label `/v1/producer-packets` multipart
// path; both shapes share this interface because the compatibility path only ever populates the
// optional PRD-shaped fields when its own source kinds happen to overlap with the strict allowlist.
export type ProducerPacketSchemaVersion = "producer-intake-decision-packet@1" | "producer-decision-packet@1";
export interface ProducerPacketProvenance { schema_version: "producer-provenance@1"; contract_version?: ProducerPacketSchemaVersion; mode: "demo"; backend: string; provider: string; external: false; read_only: true; grounding_strategy?: string; bundle_manifest_hash?: string; source_manifest_hash?: string; fallback_used?: boolean; retention_state?: string; external_evidence_enabled?: boolean; external_evidence_provider?: string | null }
export interface ProducerDecisionPacket { schema_version: ProducerPacketSchemaVersion; workflow: "producer_consolidation"; status: "succeeded"; packet_id: string; bundle_id?: string | null; created_at: string; bundle: { schema_version: "producer-source-bundle@1"; bundle_id?: string; source_count: number; source_ids: string[]; total_bytes: number; total_extracted_chars: number; manifest_hash?: string }; executive_summary: ProducerStatement; source_manifest?: ProducerSourceInventory[]; source_inventory: ProducerSourceInventory[]; exact_facts?: ProducerCanonicalItem[]; scene_index?: ProducerCanonicalItem[]; production_elements?: ProducerCanonicalItem[]; schedule_inputs?: ProducerCanonicalItem[]; budget_inputs?: ProducerCanonicalItem[]; rights_access_logistics?: ProducerCanonicalItem[]; conflicts?: ProducerCanonicalItem[]; decision_question_register?: ProducerCanonicalItem[]; gaps_and_next_steps?: ProducerCanonicalItem[]; external_evidence?: ProducerCanonicalItem[]; version_provenance: Record<string, unknown>; reconciliation: Record<string, unknown>; production_decisions: ProducerStatement[]; decision_register: ProducerRegisterEntry[]; locations_and_timing: ProducerStatement[]; cast_role_demands: ProducerStatement[]; department_requirements: ProducerStatement[]; risks_or_conflicts: ProducerStatement[]; cross_document_conflicts: ProducerStatement[]; gaps_or_questions: ProducerStatement[]; handoff: Record<string, unknown>; cited_citation_ids: string[]; citations: ProducerCitation[]; provenance: ProducerPacketProvenance; limitations: string[] }

