export interface PartnerEvent { schema_version: "partner-event@1"; event_id: string; provider_id: string | null; event_type: string; operation: PartnerOperation | null; attempt: number; state: string; delivery_id_hash?: string; error_class?: string; payload: Record<string, unknown>; occurred_at: string; redacted: true }
export interface PartnerProjection { schema_version: "partner-projection@1"; provider: PartnerCapability["provider"] | null; environment: PartnerEnvironment; endpoint_ref: string | null; auth_mode: string | null; scope_ref?: string | null; allowed_operations: PartnerOperation[]; data_classes: PartnerDataClass[]; enabled: boolean; health: PartnerCapability["health"]; readiness: PartnerReadiness; provenance: PartnerProvenance }
